const r=await Promise.allSettled([
  tools.exec_command({cmd:"sed -n '260,302p' /Users/serro/.codex/memories/MEMORY.md","max_output_tokens":3500}),
  tools.exec_command({cmd:"sed -n '9418,9450p' /Users/serro/.codex/memories/MEMORY.md","max_output_tokens":2000}),
  tools.exec_command({cmd:"command -v skillplane; command -v composio; command -v rex; command -v gh; git status --short --branch; git remote -v","max_output_tokens":2500}),
  tools.exec_command({cmd:"cat /Users/serro/.agents/skills/using-21nco-github/SKILL.md","max_output_tokens":3500})
]);r.forEach((x,i)=>text({i,result:x.status==="fulfilled"?x.value.output:x.reason}));

