name: Superfunctions Docs Cloudflare Deploy

permissions:
  contents: read

on:
  push:
    branches:
      - dev
    tags:
      - superfunctions-docs-live-*
      - superfunctions-docs-datafn-live-*
      - superfunctions-docs-filefn-live-*
      - superfunctions-docs-searchfn-live-*
      - superfunctions-docs-authfn-live-*
      - superfunctions-datafn-docs-live-*
      - superfunctions-filefn-docs-live-*
      - superfunctions-searchfn-docs-live-*
      - superfunctions-authfn-docs-live-*
    paths:
      - datafn/docs/**
      - filefn/docs/**
      - searchfn/docs/**
      - authfn/docs/**
      - docsfn/**
      - packages/docs-theme/**
      - scripts/cloudflare-docs/**
      - package.json
      - package-lock.json
      - turbo.json
      - .github/workflows/superfunctions-docs-cloudflare-deploy.yml
  workflow_dispatch:
    inputs:
      product:
        description: Docs product to deploy
        required: true
        type: choice
        default: all
        options:
          - all
          - datafn
          - filefn
          - searchfn
          - authfn
      environment:
        description: Docs environment to deploy
        required: true
        type: choice
        default: dev
        options:
          - dev
          - live

