import adapterCloudflare from "@sveltejs/adapter-cloudflare";
import { vitePreprocess } from "@sveltejs/vite-plugin-svelte";

const adapter = process.env.CLOUDFLARE_DOCS_DEPLOY === "1"
  ? adapterCloudflare()
  : adapterAuto();
const docsDeploy = process.env.CLOUDFLARE_DOCS_DEPLOY === "1";

/** @type {import('@sveltejs/kit').Config} */
const config = {
  // script:true so esbuild strips TS that Svelte 5's native stripper leaves
  // behind in published @docsfn/svelte sources (e.g. `activePath?: string` → `activePath?`).
  preprocess: vitePreprocess({ script: true }),
  kit: {
    adapter,
    alias: { "@site/docs-search": "../../scripts/docs-site/Search.svelte" },
    appDir: docsDeploy ? "docs/_app" : "_app",
    paths: {
      assets: /** @type {"" | `http://${string}` | `https://${string}`} */ (process.env.CLOUDFLARE_DOCS_ASSETS_ORIGIN ?? ""),
    },
  },
};

export default config;
<script lang="ts">
  import "../app.css";
  import DocsSiteSearch from "$lib/components/DocsSiteSearch.svelte";
  import TopBar from "@docsfn/svelte/TopBar.svelte";
  import { page } from "$app/stores";
  import { onMount, type Snippet } from "svelte";
  import { observeTopBar } from "../../../../scripts/docs-site/layout";
  import type { LayoutData } from "./$types";

  interface Props {
    data: LayoutData;
    children: Snippet;
  }

  let { data, children }: Props = $props();
  let siteRoot: HTMLDivElement;
  onMount(() => observeTopBar(siteRoot));

</script>

<div
  bind:this={siteRoot}
  class="docsfn-site-root"
  class:docsfn-docs-chrome={$page.url.pathname.startsWith("/docs")}
>
  <TopBar
    items={data.source.config.navigation?.topNav}
    searchTrigger={DocsSiteSearch}
  />
  <div class="docsfn-site-main">
    {@render children()}
  </div>
  {#if data.source.config.site.showFooter !== false}
    <footer class="docsfn-site-footer">
      <p>Built at <a href="https://21n.co" rel="noreferrer noopener">21n.co</a></p>
    </footer>
  {/if}
</div>

<style>
  .docsfn-site-root {
    min-height: 100vh;
    width: 100%;
    max-width: none;
    display: flex;
    flex-direction: column;
  }

  .docsfn-site-main {
    flex: 1;
    min-height: 0;
    display: flex;
    flex-direction: column;
  }

  .docsfn-site-footer {
    flex-shrink: 0;
    align-self: stretch;
    width: 100%;
    max-width: none;
